public class ProductDao {

    private final java.util.Map<Integer, Product> rows = new java.util.HashMap<>();

    public void save(Product product) {
        rows.put(product.getId(), product);
    }

    public java.util.Optional<Product> findById(int id) {
        return java.util.Optional.ofNullable(rows.get(id));
    }

    public java.util.List<Product> findAll() {
        java.util.List<Product> all = new java.util.ArrayList<>(rows.values());
        all.sort(java.util.Comparator.comparingInt(Product::getId));
        return all;
    }

    public boolean deleteById(int id) {
        return rows.remove(id) != null;
    }

    public boolean updatePrice(int id, double newPrice) {
        Product existing = rows.get(id);
        if (existing == null) {
            return false;
        }
        rows.put(id, new Product(id, existing.getName(), newPrice));
        return true;
    }
}

