public class ProductDaoTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static ProductDao seeded() {
        ProductDao dao = new ProductDao();
        dao.save(new Product(3, "Washer", 0.25));
        dao.save(new Product(1, "Bolt", 1.5));
        dao.save(new Product(2, "Nut", 0.5));
        return dao;
    }

    public static void main(String[] args) {
        try {
            ProductDao dao = seeded();

            check("findAll is sorted by id",
                  "[1:Bolt:1.5, 2:Nut:0.5, 3:Washer:0.25]", dao.findAll().toString());
            check("findById finds a row",
                  "Optional[2:Nut:0.5]", String.valueOf(dao.findById(2)));
            check("findById missing row is empty",
                  "Optional.empty", String.valueOf(dao.findById(99)));

            dao.save(new Product(1, "Bolt XL", 2.25));
            check("save with an existing id replaces the row without adding one",
                  "Optional[1:Bolt XL:2.25] size=3",
                  dao.findById(1) + " size=" + dao.findAll().size());

            check("deleteById existing then missing",
                  "true,false", dao.deleteById(2) + "," + dao.deleteById(2));
            check("findAll after delete",
                  "[1:Bolt XL:2.25, 3:Washer:0.25]", dao.findAll().toString());

            check("updatePrice existing returns true and keeps the name",
                  "true Optional[3:Washer:0.75]",
                  dao.updatePrice(3, 0.75) + " " + dao.findById(3));
            check("updatePrice missing returns false", false, dao.updatePrice(42, 1.0));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected a normal return but got " + e);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

